/**
 * Rate Limiter Middleware
 * Provides rate limiting for API endpoints to prevent abuse
 */

const { RateLimiterMemory, RateLimiterRedis } = require('rate-limiter-flexible');
const { logger } = require('../utils/logger');

// In-memory rate limiter (for development)
const rateLimiter = new RateLimiterMemory({
  points: 100, // Number of requests
  duration: 60, // Per 60 seconds
  blockDuration: 60 // Block for 60 seconds if limit exceeded
});

// Strict rate limiter for sensitive endpoints
const strictRateLimiter = new RateLimiterMemory({
  points: 10,
  duration: 60,
  blockDuration: 300
});

// Auth endpoint rate limiter (prevent brute force)
const authRateLimiter = new RateLimiterMemory({
  points: 5,
  duration: 60,
  blockDuration: 300
});

/**
 * General rate limiter middleware
 */
async function rateLimitMiddleware(req, res, next) {
  try {
    const key = req.ip || req.connection.remoteAddress;

    await rateLimiter.consume(key);

    // Add rate limit headers
    res.setHeader('X-RateLimit-Limit', rateLimiter.points);
    res.setHeader('X-RateLimit-Remaining', rateLimiter.getRemainingPoints ? 
      rateLimiter.getRemainingPoints(key) : 'unknown');

    next();
  } catch (rej) {
    const secs = Math.round(rej.msBeforeNext / 1000) || 1;

    res.setHeader('Retry-After', secs);
    res.setHeader('X-RateLimit-Limit', rateLimiter.points);
    res.setHeader('X-RateLimit-Remaining', 0);

    logger.warn(`Rate limit exceeded for IP: ${req.ip}`);

    res.status(429).json({
      error: 'Too many requests',
      code: 'RATE_LIMIT_EXCEEDED',
      retryAfter: secs
    });
  }
}

/**
 * Strict rate limiter for sensitive endpoints
 */
async function strictRateLimit(req, res, next) {
  try {
    const key = req.ip || req.connection.remoteAddress;

    await strictRateLimiter.consume(key);

    next();
  } catch (rej) {
    const secs = Math.round(rej.msBeforeNext / 1000) || 1;

    res.setHeader('Retry-After', secs);

    logger.warn(`Strict rate limit exceeded for IP: ${req.ip}`);

    res.status(429).json({
      error: 'Too many requests',
      code: 'RATE_LIMIT_EXCEEDED',
      retryAfter: secs
    });
  }
}

/**
 * Auth-specific rate limiter
 */
async function authRateLimit(req, res, next) {
  try {
    const key = req.ip || req.connection.remoteAddress;

    await authRateLimiter.consume(key);

    next();
  } catch (rej) {
    const secs = Math.round(rej.msBeforeNext / 1000) || 1;

    res.setHeader('Retry-After', secs);

    logger.warn(`Auth rate limit exceeded for IP: ${req.ip}`);

    res.status(429).json({
      error: 'Too many authentication attempts',
      code: 'AUTH_RATE_LIMIT_EXCEEDED',
      retryAfter: secs
    });
  }
}

module.exports = {
  rateLimiter: rateLimitMiddleware,
  rateLimitMiddleware,
  strictRateLimit,
  authRateLimit
};

const crypto = require('crypto');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const slowDown = require('express-slow-down');

// Encryption utilities
class SecurityUtils {
  // AES-256 encryption
  static encrypt(text, key = process.env.ENCRYPTION_KEY) {
    if (!key) throw new Error('Encryption key not configured');

    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from(key, 'hex'), iv);

    let encrypted = cipher.update(text, 'utf8', 'hex');
    encrypted += cipher.final('hex');

    return iv.toString('hex') + ':' + encrypted;
  }

  // AES-256 decryption
  static decrypt(encryptedText, key = process.env.ENCRYPTION_KEY) {
    if (!key) throw new Error('Encryption key not configured');

    const parts = encryptedText.split(':');
    const iv = Buffer.from(parts.shift(), 'hex');
    const encrypted = parts.join(':');

    const decipher = crypto.createDecipheriv('aes-256-cbc', Buffer.from(key, 'hex'), iv);

    let decrypted = decipher.update(encrypted, 'hex', 'utf8');
    decrypted += decipher.final('utf8');

    return decrypted;
  }

  // Hash sensitive data
  static hash(text) {
    return crypto.createHash('sha256').update(text).digest('hex');
  }

  // Generate secure token
  static generateToken(length = 32) {
    return crypto.randomBytes(length).toString('hex');
  }

  // Verify integrity
  static verifyIntegrity(data, signature, secret = process.env.JWT_SECRET) {
    const hmac = crypto.createHmac('sha256', secret);
    hmac.update(data);
    const computedSignature = hmac.digest('hex');
    return computedSignature === signature;
  }

  // Sign data
  static signData(data, secret = process.env.JWT_SECRET) {
    const hmac = crypto.createHmac('sha256', secret);
    hmac.update(JSON.stringify(data));
    return hmac.digest('hex');
  }
}

// Audit logging middleware
const auditLogger = (logger) => {
  return (req, res, next) => {
    const startTime = Date.now();

    // Log request
    logger.info('API Request', {
      method: req.method,
      url: req.url,
      ip: req.ip,
      userAgent: req.get('user-agent'),
      userId: req.user?.id,
      timestamp: new Date().toISOString()
    });

    // Capture response
    const originalSend = res.send;
    res.send = function(data) {
      const duration = Date.now() - startTime;

      logger.info('API Response', {
        method: req.method,
        url: req.url,
        statusCode: res.statusCode,
        duration: `${duration}ms`,
        userId: req.user?.id,
        timestamp: new Date().toISOString()
      });

      originalSend.call(this, data);
    };

    next();
  };
};

