/**
 * Close copilot session
 */
router.put('/session/:id/close', authMiddleware, async (req, res) => {
  try {
    const result = await pool.query(
      `UPDATE copilot_sessions 
       SET status = 'closed', ended_at = NOW(), updated_at = NOW()
       WHERE id = $1 AND user_id = $2
