 */
async function optimizeFarmerSelection(orderRequirements) {
  try {
    const {
      product_id,
      quantity_required,
      quality_requirements,
      delivery_location,
      delivery_deadline,
      price_sensitivity,
      buyer_preferences
    } = orderRequirements;

