      SELECT fi.*, fc.name as category_name 
      FROM food_items fi
      LEFT JOIN food_categories fc ON fi.category_id = fc.id
      WHERE to_tsvector('english', fi.name || ' ' || COALESCE(fi.scientific_name, '')) @@ to_tsquery('english', $1)
