      const orderData = {
        userId: 'user-123',
        items: [
          { productId: 'prod-1', quantity: 1000, price: 30 }
        ],
        shippingAddress: {
          street: '123 Main St',
          city: 'Guwahati',
          state: 'Assam',
          zip: '781001'
        }
      };

      const error = {
        status: 400,
        message: 'Insufficient stock for product prod-1'
      };

      expect(error.status).toBe(400);
      expect(error.message).toContain('Insufficient stock');
    });
  });
});

